import{_ as e,c as a,o as s,a4 as n}from"./chunks/framework.4aTu-Nia.js";const b=JSON.parse('{"title":"Vue 生命周期几问","description":null,"frontmatter":{"title":"Vue 生命周期几问","date":"2019-06-11T00:00:00.000Z","description":null},"headers":[],"relativePath":"blog/vue-time-sequence.md","filePath":"blog/vue-time-sequence.md"}'),t={name:"blog/vue-time-sequence.md"},p=n(`<h1 id="vue-生命周期几问" tabindex="-1">Vue 生命周期几问 <a class="header-anchor" href="#vue-生命周期几问" aria-label="Permalink to &quot;Vue 生命周期几问&quot;">​</a></h1><p>时序问题是我们开发过程中经常遇到的问题，比如异步代码执行顺序，组件加载销毁顺序等，涉及时序的代码思考不周，比较容易出 bug，解决起来费时间。本文谈几个 Vue 生命周期常见问题。</p><h2 id="在哪个生命周期发起数据请求" tabindex="-1">在哪个生命周期发起数据请求 <a class="header-anchor" href="#在哪个生命周期发起数据请求" aria-label="Permalink to &quot;在哪个生命周期发起数据请求&quot;">​</a></h2><p>在哪个生命周期最早能访问 props 和 data？</p><p>在哪个生命周期最早能访问 DOM？如何访问？</p><p>beforeCreate 可以最早调用接口。但实例未创建，无法访问 data。在 vuex/vue-router 中常用。所以，数据请求一般写在 created 中。</p><p><a href="https://stackoverflow.com/questions/49577394/which-vuejs-lifecycle-hook-must-asynchronous-http-requests-be-called-in" target="_blank" rel="noreferrer">vue.js - Which VueJS lifecycle hook must Asynchronous HTTP requests be called in? - Stack Overflow</a></p><h2 id="同组件新旧实例生命周期顺序" tabindex="-1">同组件新旧实例生命周期顺序 <a class="header-anchor" href="#同组件新旧实例生命周期顺序" aria-label="Permalink to &quot;同组件新旧实例生命周期顺序&quot;">​</a></h2><p>问题：新实例创建时，旧实例完成销毁了吗？</p><p>在项目中遇到这个场景，以为新实例创建要在旧实例销毁后才会执行。其实不然，新实例创建钩子可能先于旧实例销毁钩子。</p><p>推理：没有必要等旧实例销毁，因为销毁钩子可能存在阻塞。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span>new created:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>old beforeDestroy:</span></span>
<span class="line"><span>old destroyed:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>new mounted</span></span></code></pre></div><h2 id="父子组件生命周期顺序" tabindex="-1">父子组件生命周期顺序 <a class="header-anchor" href="#父子组件生命周期顺序" aria-label="Permalink to &quot;父子组件生命周期顺序&quot;">​</a></h2><p>原则：从外到内，再从内到外，遵循洋葱模型。</p><table><thead><tr><th>created</th><th>mounted</th><th>beforeDestroy</th><th>destroyed</th></tr></thead><tbody><tr><td>外先</td><td>内先</td><td>外先</td><td>内先</td></tr></tbody></table><p>父子生命周期执行顺序如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span>parent created:</span></span>
<span class="line"><span>child created:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>child mounted:</span></span>
<span class="line"><span>parent mounted:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>parent beforeDestory:</span></span>
<span class="line"><span>child beforeDestroy:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>child destroyed</span></span>
<span class="line"><span>parent destroyed</span></span></code></pre></div><h2 id="mixins-与组件生命周期" tabindex="-1">mixins 与组件生命周期 <a class="header-anchor" href="#mixins-与组件生命周期" aria-label="Permalink to &quot;mixins 与组件生命周期&quot;">​</a></h2><p>mixins 先于当前组件</p><p><a href="https://github.com/Advanced-Frontend/Daily-Interview-Question/issues/128#issuecomment-617239786" target="_blank" rel="noreferrer">第 78 题：Vue 的父组件和子组件生命周期钩子执行顺序是什么 · Issue #128 · Advanced-Frontend/Daily-Interview-Question</a></p>`,20),l=[p];function i(o,r,c,d,h,u){return s(),a("div",null,l)}const _=e(t,[["render",i]]);export{b as __pageData,_ as default};
